import{_ as t,o as a,c as o,ak as r}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Privacy & data flow","description":"","frontmatter":{"title":"Privacy & data flow","lang":"en-US"},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1785168892000}'),i={name:"privacy.md"};function n(s,e,d,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-data-flow" tabindex="-1">Privacy &amp; data flow <a class="header-anchor" href="#privacy-data-flow" aria-label="Permalink to &quot;Privacy &amp; data flow&quot;">​</a></h1><p>Test results are unusually revealing: they carry your source paths, error messages, screenshots of your app, network calls, and sometimes your git history. That&#39;s a good reason to know exactly where the bytes go. This page is the inventory.</p><p>The short version: <strong>Piwi makes no outbound network call you didn&#39;t configure.</strong> There is no telemetry, no usage analytics, no update check, no crash reporting, and no license or activation call. An instance running on an air-gapped network works the same as one on the internet.</p><h2 id="what-leaves-your-server" tabindex="-1">What leaves your server <a class="header-anchor" href="#what-leaves-your-server" aria-label="Permalink to &quot;What leaves your server&quot;">​</a></h2><p>Every outbound connection Piwi can make is something you switched on:</p><table tabindex="0"><thead><tr><th>Destination</th><th>When</th><th>Carries</th></tr></thead><tbody><tr><td>Your AI provider</td><td>Only if you configure <a href="./ai-diagnosis.html">AI diagnosis</a></td><td>The diagnosis context: error text, failing steps, the relevant git diff, and — if enabled — failure screenshots</td></tr><tr><td>Your git host</td><td>Only if you connect a repository with a token</td><td>API reads: commits and diffs for the project&#39;s repo</td></tr><tr><td>Your SMTP server</td><td>Only if you configure <a href="./notifications.html">email notifications</a></td><td>Notification and account emails</td></tr><tr><td>Your Slack / webhook URLs</td><td>Only for subscriptions you create</td><td>The event payload (run status, cluster, test names)</td></tr><tr><td>Your S3 endpoint</td><td>Only if you switch <a href="./storage.html">storage</a> to S3</td><td>Trace files, HTML reports, attachments</td></tr><tr><td>Google / GitHub</td><td>Only if you enable <a href="./authentication.html#oauth-google-github">OAuth sign-in</a></td><td>The standard OAuth exchange</td></tr></tbody></table><p>Nothing on that list has a default. With none of them configured, a Piwi instance talks to nobody.</p><p>The <strong>AI provider</strong> is the one worth pausing on, because it&#39;s the only case where your code and error text can leave your network. It&#39;s opt-in, it goes only to the endpoint <em>you</em> set — including a local model over Ollama or vLLM, in which case nothing leaves the machine at all — you can preview the exact context before it&#39;s sent, and you can cap its size. See <a href="./ai-diagnosis.html#privacy">AI diagnosis → Privacy</a>.</p><h2 id="what-never-leaves-your-server" tabindex="-1">What never leaves your server <a class="header-anchor" href="#what-never-leaves-your-server" aria-label="Permalink to &quot;What never leaves your server&quot;">​</a></h2><ul><li><strong>Traces.</strong> The Playwright trace viewer is bundled and served by your own instance at <code>/trace-viewer/</code>. Opening a trace from Piwi never uploads it anywhere — unlike sending a colleague to the hosted <code>trace.playwright.dev</code>.</li><li><strong>The API reference.</strong> <code>/docs</code> is rendered in-app from your instance&#39;s own OpenAPI spec, with no third-party CDN, so it works offline.</li><li><strong>Screenshots, videos, HTML reports.</strong> Stored on your disk or your S3 bucket, served by your instance.</li><li><strong>Your IDE mapping.</strong> The <a href="./ide-integration.html">Open in IDE</a> workspace root lives in your browser&#39;s local storage, because the source is on your machine, not the server&#39;s. It is never sent to the dashboard.</li></ul><h2 id="what-piwi-deliberately-does-not-capture" tabindex="-1">What Piwi deliberately does not capture <a class="header-anchor" href="#what-piwi-deliberately-does-not-capture" aria-label="Permalink to &quot;What Piwi deliberately does not capture&quot;">​</a></h2><p>Some data is skipped at the source, so it never exists to leak:</p><ul><li><strong>Input values.</strong> The <a href="./capture-fixtures.html">capture fixtures</a> record what an element <em>is</em> — role, accessible name, test id — never what was typed into it. A password field&#39;s value is never captured.</li><li><strong>Storage and cookie values.</strong> Page state records the <em>names</em> of <code>localStorage</code> /<code>sessionStorage</code> keys and their value lengths, and cookie names with their flags. Never the values.</li><li><strong>Sensitive headers.</strong> <code>Authorization</code>, <code>Cookie</code> and friends are masked server-side in the trace network view, and token-shaped strings in URLs and bodies are masked too — so a bearer token that appeared in a request doesn&#39;t end up readable in the dashboard.</li><li><strong>Backend logs, in production.</strong> The <a href="./backend-logs.html">backend-log integrations</a> emit their header only in development and test environments by default.</li></ul><h2 id="secrets-at-rest" tabindex="-1">Secrets at rest <a class="header-anchor" href="#secrets-at-rest" aria-label="Permalink to &quot;Secrets at rest&quot;">​</a></h2><p>Credentials you store in the dashboard — AI API keys, SCM tokens, webhook signing secrets — are encrypted with AES-256-GCM using <code>PIWI_SECRET_KEY</code>. <strong>Set it in production.</strong> With the variable unset, Piwi falls back to a hardcoded default string that is published in this repository — the values are encrypted, but against a key anyone can look up, so treat that as no protection at all.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console.log(require(&#39;node:crypto&#39;).randomBytes(32).toString(&#39;hex&#39;))&quot;</span></span></code></pre></div><p>API keys are stored as SHA-256 hashes and shown exactly once, at creation. A leaked database gives an attacker no usable key.</p><p>Secrets provided by environment variable are never written to the database and never returned by the API — the settings UI shows them as read-only with a lock badge.</p><h2 id="the-demo" tabindex="-1">The demo <a class="header-anchor" href="#the-demo" aria-label="Permalink to &quot;The demo&quot;">​</a></h2><p>The <a href="https://piwitests.github.io/demo/" target="_blank" rel="noreferrer">live demo</a> has no backend. It runs the real application against an in-browser SQLite database seeded with fake data, inside a service worker. Nothing you click there reaches a server, and there is nothing for it to collect.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Data you keep is data you&#39;re responsible for. Piwi can prune it for you: set <code>PIWI_RETENTION_DAYS</code> for nightly automatic pruning of old runs and their files, or delete in bulk from <strong>Settings → Storage</strong>. Deleting a run removes its executions, traces, reports, and any evidence payloads no longer referenced by anything else. See <a href="./storage.html#data-retention">Storage → Data retention</a>.</p><h2 id="verifying-any-of-this" tabindex="-1">Verifying any of this <a class="header-anchor" href="#verifying-any-of-this" aria-label="Permalink to &quot;Verifying any of this&quot;">​</a></h2><p>You don&#39;t have to take the page&#39;s word for it. The source is MIT-licensed and the outbound surface is small enough to audit: watch the container&#39;s egress, or read <a href="https://github.com/PiwiTests/platform/tree/main/application/server/utils" target="_blank" rel="noreferrer"><code>server/utils/</code></a> — the AI provider, SCM, SMTP, storage and notification clients are the only things there that open a socket.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./authentication.html">Authentication</a> — roles, API keys, and project-level access</li><li><a href="./deployment.html#security">Deployment → Security</a> — hardening a public instance</li><li><a href="./comparison.html#is-my-data-safe-does-piwi-phone-home">Why Piwi?</a> — the same question, short form</li></ul>',26)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
